import mongoose from "mongoose";
import WorkCalendar from "../src/models/workCalendarModel.js";
import dotenv from "dotenv";

// Load environment variables
dotenv.config({ path: './backend/.env' });

const fixWorkItemsAllDay = async () => {
  try {
    console.log("🔧 Connecting to database...");
    await mongoose.connect(process.env.MONGO_URI);
    console.log("✅ Connected to database");

    console.log("\n🔍 Finding work calendar entries from work items...");
    
    // Find all work calendar entries that were auto-generated from work items
    const workCalendarEntries = await WorkCalendar.find({
      sourceModel: 'WorkItem',
      isAutoGenerated: true
    });

    console.log(`Found ${workCalendarEntries.length} work calendar entries to update`);

    let updatedCount = 0;

    for (const entry of workCalendarEntries) {
      // Update to be all-day event
      const wasAllDay = entry.isAllDay;
      entry.isAllDay = true;
      
      await entry.save();
      updatedCount++;
      
      console.log(`✅ Updated: ${entry.title} (was all-day: ${wasAllDay})`);
    }

    console.log(`\n✅ Update completed!`);
    console.log(`📊 Summary:`);
    console.log(`   Total entries updated: ${updatedCount}`);

  } catch (error) {
    console.error("❌ Error during update:", error);
  } finally {
    await mongoose.disconnect();
    console.log("🔌 Disconnected from database");
  }
};

// Run the fix
fixWorkItemsAllDay();